from typing import List

from .message_handling import (Structure, SMessageAddress, SMessageHeader, SBrowserObject,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from ..utils import get_context_id, get_procedure_id
from .sack_reflection_interface import EReportingMode, EBrowserObjectName, BTS_BROWSER_BASE


MAX_NUM_OF_LOCAL_CELLS = 12
MAX_SCCPCH_CELL = 3             # Nokia supported value 3, 3GPP 32
MAX_PRACH_CELL = 4              # Nokia supported value 4, 3GPP 16
MAX_NUMBER_OF_RADIUS_SPLIT = 4  # See parameters below
CELL_ID_WORKAROUND_FOR_PIC = 0x80000000


BROWSER_BTS_HSUPA_CELLS_REQ_MSG = BTS_BROWSER_BASE + 0x029
BROWSER_BTS_HSUPA_CELLS_ACK_MSG = BTS_BROWSER_BASE + 0x027


class SBtsBch(Structure):
    _fields_ = [
        ('bchId', u32),
        ('internalChannelState', u32),
        ('numberOfBchs', u32),
        ('messageAddressOfDsp', SMessageAddress),
    ]


class SBtsFachPch(Structure):
    _fields_ = [
        ('fachPchId', u32),
        ('internalChannelState', u32),
        ('numberOfFachPchs', u32),
        ('messageAddressOfAtm', SMessageAddress * 1),
        ('messageAddressOfDsp', SMessageAddress)
    ]


class SBtsRach(Structure):
    _fields_ = [
        ('rachId', u32),
        ('internalChannelState', u32),
        ('numberOfRachs', u32),
        ('messageAddressOfAtm', SMessageAddress),
        ('messageAddressOfDsp', SMessageAddress * (MAX_NUMBER_OF_RADIUS_SPLIT * 2))
    ]


class SBtsCell(Structure):
    _fields_ = [
        ('cellId', u32),
        ('cellAvailabilityState', u32),
        ('localCellResId', u32),
        ('localCellRecourseState', u32),
        ('internalCellState', u32),
        ('numberOfBchs', u32),
        ('btsBch', SBtsBch * 1),
        ('numberOfFachPchs', u32),
        ('btsFachPch', SBtsFachPch * MAX_SCCPCH_CELL),
        ('numberOfRachs', u32),
        ('btsRach', SBtsRach * MAX_PRACH_CELL),
    ]


@register_message
class BrowserBtsCellsReq(RequestMessage):
    id = 0x1e07

    _fields_ = [
        ('header', SMessageHeader),
        ('reportingMode', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('subsystem', SBrowserObject),
        ('browserObject', SBrowserObject)
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserBtsCellsReq, self).__init__(board, cpu, *args, **kwargs)
        self.reportingMode = EReportingMode.EReportingMode_Single
        self.contextId = get_context_id()
        self.procedureId = get_procedure_id()
        self.subsystem.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.subsystem.objectId = 0
        self.browserObject.objectName = EBrowserObjectName.EBrowserObjectName_Cpu
        self.browserObject.objectId = cpu


@register_message
class BrowserBtsCellsAck(ResponseMessage):
    id = 0x1e06

    _fields_ = [
        ('header', SMessageHeader),
        ('contextId', u32),
        ('procedureId', u32),
        ('cellCountTotal', u32),
        ('cellCountInThisMessage', u32),
        ('btsCell', SBtsCell * MAX_NUM_OF_LOCAL_CELLS),
    ]


class BrowserBtsCellsQuery(Query):
    def __init__(self, req, resp):
        super(BrowserBtsCellsQuery, self).__init__(req, resp)

        self.bts_cells = []
        self._actual_count = 0
        self._expected_total_count = 0

    def _handle_response(self):
        self._expected_total_count = self.resp_msg.cellCountTotal
        count_in_this_message = self.resp_msg.cellCountInThisMessage
        self._actual_count += count_in_this_message

        for c in self.resp_msg.btsCell[:count_in_this_message]:
            self.bts_cells.append(c.get_copy())

    def _decide_if_complete(self):
        if self._actual_count == self._expected_total_count:
            self.complete = True


class CellListInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def get_cells(self, board, cpu):
        # type: (int, int) -> List[SBtsCell]
        query = BrowserBtsCellsQuery(BrowserBtsCellsReq(board, cpu), BrowserBtsCellsAck())
        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()
        return query.bts_cells

    def get_cell_ids(self, board, cpu):
        # type: (int, int) -> List[int]
        bts_cells = self.get_cells(board, cpu)
        cell_ids = []
        for cell_structure in bts_cells:
            cell_id = int(cell_structure.cellId)
            if cell_id == CELL_ID_WORKAROUND_FOR_PIC:
                cell_id = int(cell_structure.localCellResId)
            cell_ids.append(cell_id)
        return sorted(cell_ids)


